              condition: "点电荷；观察点与电荷的距离 $r$ 远大于电荷自身尺度。$q$ 取正号时 $\\hat{r}$ 表示场背离电荷，$q$ 取负号时场指向电荷。",
              note: "$\\hat{r}$ 读作「r 帽」，是一个长度为 1、只用来指明方向的矢量。把标量部分 $k_e q/r^2$ 与方向部分 $\\hat{r}$ 分开写，是为了在叠加时先把方向问题处理干净。"
