        {
          type: "concept",
          title: "从公式回到世界：这些数在哪里用得上",
          md: "- **先看一张量级表，学会判断答案合不合理。** 氢原子内部，电子感受到的场强约 $5\\times10^{11}\\ \\text{N/C}$；晴天大气近地面的竖直场约 $120\\ \\text{N/C}$，雷雨云底部可达 $10^4\\ \\text{N/C}$；走在地毯上摩擦起电后，人体表面的场在 $10^5\\ \\text{N/C}$ 量级；电离层与地面之间整体约有 $3\\times10^5\\ \\text{V}$ 的电势差。**凡是算出来的场强落在 $10^{-2}$ 到 $10^6\\ \\text{N/C}$ 之外，都要停下来想一想是不是漏了某个因子。**\\n- **干燥空气的击穿场强约 $3\\times10^6\\ \\text{V/m}$。** 这是一个非常有用的判据：它解释了为什么冬天碰门把手会「啪」一下（指尖附近的场强超过击穿值，空气被电离、形成一条导电通道，电荷在两三毫米的距离上中和），也解释了为什么高压设备要泡在绝缘油里或者充六氟化硫气体——那些介质的击穿场强比空气高出好几倍。\\n- **静电屏蔽与法拉第笼。** 高斯面取在导体内部时，因为导体内部场强为零（原因见第二讲），面内的净电荷必为零，所以电荷只能待在导体表面。这条结论的直接应用是一个空心的金属壳：把敏感元件放在壳里，外部电荷产生的场在壳外被重新排布的表面电荷抵消掉，壳内几乎无场。微波炉门上的金属网、飞机的机身、实验室里测量微弱电信号的屏蔽箱，用的都是同一件事。注意网眼要远小于波长才有效，这是后面电磁波那一讲的内容。\\n- **静电除尘与静电喷涂。** 高压电晕放电让烟尘粒子带电，带电梯之间的电场再把它们吸到收集极上。这类装置里的场强设计在 $10^5\\ \\text{V/m}$ 量级：太低吸不动，太高会频繁打火。算除尘器的效率时，先要知道带电粒子在给定场强下的漂移速度，而漂移速度正比于场强乘上粒子所带的电量——所以整条计算链的第一环就是这里的 $\\vec{F} = q\\vec{E}$。\\n- **一次实打实的量级估算：静电喷漆为什么比刷漆省料。** 设喷嘴与工件之间加 $60\\ \\text{kV}$、间距 $0.3\\ \\text{m}$，平均场强约 $2\\times10^5\\ \\text{V/m}$。一滴直径 $20\\ \\mu\\text{m}$ 的漆液带上约 $10^{-14}\\ \\text{C}$ 的电量，受到的电力约 $F = qE = 10^{-14}\\times2\\times10^5 = 2\\times10^{-9}\\ \\text{N}$。这滴漆的质量约 $4\\times10^{-12}\\ \\text{kg}$，重力约 $4\\times10^{-11}\\ \\text{N}$。比较一下：电力是重力的 50 倍，所以电场完全能压住重力、把漆滴拉向工件而不是让它飘散——这就是静电喷涂能把附着率从刷漆的六成提到九成以上的物理依据。**先估量级、再决定要不要细算**，这类判断比多背一条公式有用得多。\\n- **别忘了这一章的全部结论都建立在一个前提上：电荷静止。** 一旦电荷动起来，就会出现三种新效应：运动的电荷产生磁场（第三讲）、变化的磁场反过来产生电场（第四讲）、以及电荷分布随时间变化时基尔霍夫式的电流连续性。后面三讲就是在逐步松开「静止」这个前提。"
        }
