        {
          type: "concept",
          title: "从公式回到世界：电容、电势差与工程中的量级",
          md: "- **先把常用电容的量级排一排**：芯片内部栅极电容约 $10^{-15}\\ \\text{F}$（飞法）；陶瓷小电容 $10^{-9}$ 到 $10^{-6}\\ \\text{F}$；电解电容 $10^{-6}$ 到 $10^{-1}\\ \\text{F}$；超级电容单个可达 $10^2\\ \\text{F}$；而地球作为孤立导体的电容只有约 $7.1\\times10^{-4}\\ \\text{F}$（由 $C = 4\\pi\\varepsilon_0 R_\\oplus$ 算出，$R_\\oplus = 6.371\\times10^6\\ \\text{m}$）。**最后这个数相当反直觉：整颗地球的电容还不到一毫法。** 原因很简单——孤立导体的电容与它的尺寸成正比，而地球在宇宙尺度上并不算大；要电容大，需要的是「两块导体靠得很近」，而不是「导体本身很大」。\\n- **超级电容为什么能做得那么大。** 因为它的两块电极之间只有一层纳米级的离子层，等效间距极小；再加上电极是活性炭，内部孔隙让有效面积达到每克上千平方米。回到公式 $C = \\varepsilon_r\\varepsilon_0 S/d$：$d$ 小到纳米、$S$ 大到上千平方米，电容自然暴涨。它的代价是耐压很低（单个约 2.7 V），必须串联使用，而串联会带来均压问题。\\n- **一次量级估算：手机电池与电容器差多少。** 一块 $3000\\ \\text{mA}\\cdot\\text{h}$ 的锂电池在 $3.7\\ \\text{V}$ 下储存约 $3000\\times10^{-3}\\times3600\\times3.7 \\approx 4.0\\times10^4\\ \\text{J}$。而本讲算出的 $88.5\\ \\text{pF}$ 电容器储 $4.43\\times10^{-9}\\ \\text{J}$。两者差了 13 个数量级。即使是 1 F 的超级电容充到 2.7 V 也只储 $\\frac{1}{2}\\times1\\times2.7^2 \\approx 3.6\\ \\text{J}$。**结论：电容器适合在极短时间内释放大功率（相机的闪光灯、电磁炮、激光器的泵浦源），不适合长时间储存能量——电池才是干这件事的。** 这个「功率密度与能量密度各有取舍」的判断，比记住任何一条公式都更能指导实际选型。\\n- **为什么高压输电要用很高的电压。** 输送同样的功率 $P$，线路电流 $I = P/U$，线路上的焦耳损耗是 $I^2R$。把电压升高 10 倍，电流降到十分之一，损耗降到百分之一。这就是为什么远距离输电用 $220\\ \\text{kV}$ 甚至 $1000\\ \\text{kV}$。但电压不能无限升高：空气击穿场强 $3\\times10^6\\ \\text{V/m}$ 决定了导线与杆塔之间必须留出足够的距离，也决定了要用绝缘子串、要充绝缘气体。**「击穿场强」这个本讲的静电场结论，直接决定了电网的物理尺寸。**\\n- **雷电里的数。** 典型雷雨云底部与地面之间有约 $10^8$ 到 $10^9\\ \\text{V}$ 的电势差，一次闪电转移约 $15$ 到 $350\\ \\text{C}$ 的电荷，释放能量在 $10^9\\ \\text{J}$ 量级（相当于几百公斤 TNT）。云底附近的场强在 $10^4\\ \\text{V/m}$ 量级，看起来离击穿值还差两个数量级——真正触发击穿的机制是梯级先导：一小段空气先被局部电离、形成导电通道的尖端，尖端附近的场强被放大十倍以上，于是击穿一步步向地面推进。**「尖端附近场强被放大」这条结论，正是前面尖端放电那一段的直接应用。**\\n- **这一讲所有结论的共同前提，还是「电荷静止」。** 电容器一旦接上交流电源，电流就会来回流动，板间的场也在变，那时单靠静电场这套记账方式就不够用了：需要引入位移电流（第五讲），也需要给「电容器两端电压与电流的相位关系」补一条新的规律。但即便到那时，$C = Q/U$ 这个定义式依然成立，$W = \\frac{1}{2}CU^2$ 依然成立——**一个模型被扩展时，原来在适用范围内成立的部分会原样保留下来。**"
        }
