              condition: "完整的圆形电流；取的是圆心这一点的场。偏离圆心后要大打折扣，圆心附近 $B$ 的变化很小（一阶为零），所以这个式子在圆心附近是一个可用的近似。",
              note: "方向由右手判定：四指沿电流方向弯曲，拇指指向圆心处的磁场方向。把圆环绕成很多圈就得到螺线管，圆心处磁场正是螺线管公式的来源。"
