          back: "由 $v_d = I/(neS)$，铜导线（$n \\approx 8.5\\times10^{28}\\ \\text{m}^{-3}$、$S = 1.0\\ \\text{mm}^2$、$I = 1.0\\ \\text{A}$）算得 $v_d \\approx 7.3\\times10^{-5}\\ \\text{m/s}$。但推动电子的**电场**以接近光速（导线周围介质中的电磁波速）在导线里建立，导线各处本来都塞满自由电子，电场一到全部同时开始漂移。",
