          back: "分两步：先用 $B = \\dfrac{\\mu_0 I_1}{2\\pi a}$ 算出第一根导线在第二根处产生的磁场，再用 $F = BI_2L\\sin\\theta$（平行时 $\\sin\\theta = 1$）算出第二根受到的力，方向由 $\\vec{F} = I\\vec{L}\\times\\vec{B}$ 判定。同向电流互相吸引、反向互相排斥。单位长度上的力为 $F/L = \\dfrac{\\mu_0 I_1I_2}{2\\pi a}$。",
