        {
          type: "pitfall",
          title: "磁介质这一讲的七个高频错误",
          items: [
            "**把「磁场强度 $\\vec{H}$」当成「磁感应强度 $\\vec{B}$」的另一个名字。** 两个量单位不同（$H$ 是 A/m，$B$ 是 T）、物理含义不同（$H$ 只由自由电流驱动，$B$ 是总磁场）。在真空里 $B = \\mu_0H$，两者只差一个常数，所以容易混；一旦有了介质，$B = \\mu_0\\mu_rH$，差一个可能到 $10^5$ 的因子，混用会差出五个数量级。**判断自己有没有搞混的简单办法：看单位。** 题目给的是 T 还是 A/m？",
            "**以为铁磁材料的磁导率是一个固定常数。** 硅钢的 $\\mu_r$ 在小场下可能只有几百，在最佳工作点附近可以到几千甚至上万，进入饱和后又掉到接近 1。它还与温度、频率、机械应力有关。所以「铁芯的磁导率是 2000」这句话只在指定的工作点与温度下成立，正式设计必须查磁化曲线。",
            "**把饱和当成「材料坏了」。** 饱和是铁磁材料的正常物理极限：所有磁畴都已经转到与外场一致，没有更多的磁矩可以贡献。进入饱和后磁导率骤降、电感急剧减小、电流迅速上升，这是开关电源设计中必须避免的工作区，但它不是故障。对策是加大铁芯截面积或增大气隙。",
            "**以为「顺磁质会被磁铁吸引、抗磁质会被排斥」所以差别很大。** 顺磁与抗磁的磁化率都在 $10^{-5}$ 量级，在普通磁铁附近的力小到难以察觉。只有在强磁场（十几特斯拉的超导磁体）里，抗磁效应才强到能让水、甚至活体（主要是水）悬浮起来——那就是著名的「磁悬浮青蛙」实验。**分辨顺磁与抗磁的可靠办法不是看吸引还是排斥，而是测磁化率的大小与温度依赖：顺磁的 $M$ 随 $1/T$ 下降，抗磁几乎不随温度变化。**",
            "**忘记「所有物质都有抗磁成分」。** 抗磁效应来自外场在原子内部感生的反向环流，任何物质都躲不掉；它之所以在顺磁与铁磁材料里看不见，只是被更大的效应盖住了。判断一种材料的净磁性，本质上是在比较几个效应的大小。",
            "**仿真的诚实说明（本讲两个交互）。** ① 带电粒子仿真走的是理想化的路线，也就是「把与问题无关的特征删掉、只保留关键特征」这种做法（这一套做法叫做理想化）：它假定磁场处处均匀、粒子是一个没有体积的点电荷，不包含粒子的自旋磁矩、不考虑相对论效应、不考虑辐射损失。真实原子里的电子不能用「经典点电荷绕圈」来看待——电子的磁矩主要来自自旋这个量子属性，经典图像只能帮助理解「回旋半径反比于磁场、正比于质量」这个比例关系，不能用来算原子的磁矩数值。② 磁化过程快照是手工编排的状态序列，不是数值求解磁畴运动；真实材料里磁畴壁的钉扎与解钉扎是一个包含缺陷、应力、温度与晶粒取向的复杂统计过程，同一种牌号的硅钢在不同批次之间损耗都可能相差 10% 以上。**所以这一讲的仿真只能帮你建立机制性的理解，任何要写进设计文档的磁性数据都必须来自材料手册的实测曲线。**",
            "**把磁路类比用过了头。** 电路里的电流全部被约束在导线里（漏电流几乎为零），而磁路里的磁通量会从任何地方漏出去——空气、支架、相邻的铁芯都能分走一部分。所以磁路法算出的磁通量通常偏大，气隙越大偏差越大。工程上要乘一个漏磁系数（常取 1.05 到 1.2），或者干脆用有限元数值计算。**「类比」是帮助理解与快速估算的工具，不是普适的定律。**",
            "- **先看一组量级：一块钕铁硼永磁体能干什么。** 常见的钕铁硼牌号剩磁 $B_r$ 约 $1.2\\ \\text{T}$、矫顽力 $H_c$ 约 $9\\times10^5\\ \\text{A/m}$。它的最大磁能积 $(BH)_{\\max}$ 在 $3\\times10^5\\ \\text{J/m}^3$ 量级。一块 $10\\ \\text{cm}^3$（即 $10^{-5}\\ \\text{m}^3$）的小磁体，磁能约 $3\\ \\text{J}$，能牢牢吸住几公斤的铁——**这就是为什么现在的电机、耳机、音箱、风力发电机比三十年前小得多**：不是电路变了，是磁体变强了。\\n- **一次量级估算：一台 2 MW 风力发电机要用多少磁体。** 直驱式永磁风力发电机每兆瓦装机大约需要 0.6 到 1 吨钕铁硼，2 MW 就是 1.2 到 2 吨。这样算下来，磁体的成本在整机成本中占了可观的一块。**这个估算也解释了另一个现象：为什么钕、镝这些稀土元素的价格波动会直接影响风电与电动车的成本**——从「磁滞回线」这样一个实验室概念出发，一路推到了产业经济学。\\n- **变压器铁芯的两条损耗路径与对策。** 磁滞损耗由回线面积决定，对策是选窄回线的软磁材料（取向硅钢的回线特别窄，因为它的晶粒被轧制工艺定向排列过）；涡流损耗由交变磁通在铁芯内部激发的环流决定，对策是把铁芯做成厚度 $0.23$ 到 $0.35\\ \\text{mm}$ 的薄片、片间涂绝缘漆叠压，或者用电阻率高达 $10^{6}$ 倍于金属的铁氧体。**这两条损耗路径分别对应本讲与上一讲的两条公式，缺一条都算不准变压器的效率。**\\n- **磁记录：把磁滞回线当存储器用。** 硬盘的每一个比特都写在一个小磁畴区域的磁化方向上。要可靠地保存十年，需要材料有足够大的 $B_r$ 与 $H_c$（防止热扰动把方向翻过去）；但要能快速写入，$H_c$ 又不能太大（写入磁头产生的场有限）。**这正是「硬磁要宽回线」这条结论在存储技术里的直接体现，也是硬盘容量提升缓慢的物理原因之一**：提高存储密度要缩小每个比特的体积，而体积越小越容易被热扰动翻转（超顺磁极限），必须在材料上找新的平衡点。\\n- **磁屏蔽为什么用坡莫合金而不是铜。** 静磁场的屏蔽与静电屏蔽的逻辑不同：静电屏蔽靠导体内部场强为零，而静磁场没有「磁荷」可以流动。磁屏蔽的思路是给磁感线提供一条**低磁阻的绕行路径**——用高 $\\mu_r$ 的坡莫合金做成罩子，磁感线更愿意从罩壁里走，罩内的场就被削弱了。屏蔽效果取决于罩壁的厚度与 $\\mu_r$ 的乘积，所以坡莫合金（$\\mu_r$ 可达 $10^5$）比普通铁皮（$10^3$）有效得多。**注意这与「用铁皮挡磁场」的直觉不同：屏蔽层并不是把磁场「挡住」，而是把它「引开」。**\\n- **最后把这一讲放回整门课的位置。** 到这里，我们已经把「电产生磁」「磁产生电」「物质如何响应磁」三件事分别写清楚了。但要得到完整的麦克斯韦方程组，还缺一块拼图：变化电场会不会也产生磁？这个问题的答案（位移电流）是下一讲的开端，而它一旦补上，电磁波就会从方程里自己掉出来——那时我们会发现，光就是电磁波，而这一讲里所有关于介质的讨论，都会在「折射率 $n = \\sqrt{\\mu_r\\varepsilon_r}$」这一个式子里重新出现。"
          ]
        }
