              units: "$I_d$: A；$\\Phi_E$: N·m²/C；$J_d$: A/m²；$\\varepsilon_0$: F/m。核对：$\\varepsilon_0\\Delta\\Phi_E/\\Delta t$ 的单位是 (C²/(N·m²))·(N·m²/C)/s = C/s = A，一致。",
              condition: "位移电流出现在电场随时间变化的地方，最典型的场合是电容器的极板之间（那里传导电流为零，而位移电流恰好等于导线里的传导电流）。恒定电场不产生位移电流。",
