            "**把位移电流当成「真的有电荷在极板之间流动」。** 位移电流只是「变化的电场」这种等效说法，它不携带电荷、不产生焦耳热、不需要任何物质。真空中的电磁波里，位移电流项处处存在，而那里连一个电荷都没有。**把「等效」当成「就是」，会让人去找一种不存在的粒子。**",
