            "**在介质中把频率也一起改掉。** 光从空气进入玻璃，速度降为 $1/n$、波长也降为 $1/n$，但**频率由波源决定、跨越界面时不改变**。这一点决定了折射、干涉、衍射里所有的定量关系（比如双缝条纹间距 $\\Delta y = \\lambda D/d$ 里的 $\\lambda$ 必须取介质中的波长）。把频率也改掉，颜色就会变——而实验告诉我们，光进入玻璃后颜色不变。",
