          type: "fill",
          q: "真空中一束电磁波的电场振幅为 $E_0 = 100\\ \\text{V/m}$。它的平均能流密度（强度）为 ______ W/m²（取 $\\mu_0 = 1.2566\\times10^{-6}\\ \\text{N/A}^2$、$c = 2.998\\times10^8\\ \\text{m/s}$，保留三位有效数字）。",
          answer: ["13.3", "13.28", "13.3"],
